-- Replica schema (LOCAL THROWAWAY ONLY). Mirrors the live columns used by S1..S6b.
drop schema if exists public cascade; create schema public;
drop schema if exists auth cascade; create schema auth;
do $$ begin
  if not exists (select 1 from pg_roles where rolname='anon') then create role anon nologin; end if;
  if not exists (select 1 from pg_roles where rolname='authenticated') then create role authenticated nologin; end if;
  if not exists (select 1 from pg_roles where rolname='service_role') then create role service_role nologin bypassrls; end if;
end $$;
grant usage on schema public, auth to anon, authenticated, service_role;
create function auth.uid() returns uuid language sql stable as
 $$ select nullif(coalesce(current_setting('request.jwt.claim.sub', true), ''), '')::uuid $$;
grant execute on function auth.uid() to public;
alter default privileges in schema public grant all on tables to anon, authenticated, service_role;
alter default privileges in schema public grant execute on functions to anon, authenticated, service_role;

create table profiles (id uuid primary key, role text not null default 'shop_owner', created_at timestamptz default now(), full_name text, store_id bigint, phone text, is_active boolean default true, is_admin boolean default false, email text, page_permissions jsonb);
create table organizations (id bigint generated by default as identity primary key, name text not null, owner_id uuid not null, is_active boolean default true, created_at timestamptz default now(), country text not null default 'SA', currency text not null default 'SAR', plan text not null default 'trial', subscription_status text not null default 'trial', trial_started_at date, trial_ends_at date, max_users integer, is_internal boolean not null default false, internal_notes text, tax_number text, name_x text);
create table organization_groups (id bigint generated by default as identity primary key, organization_id bigint not null references organizations(id), name text not null, is_active boolean default true, created_by uuid);
create table organization_members (id bigint generated by default as identity primary key, organization_id bigint not null references organizations(id), user_id uuid not null, role text not null default 'viewer');
create table shops (id bigint generated by default as identity primary key, shop_name text not null, phone text, whatsapp text, google_maps_url text, logo_url text, commercial_registration text, website text, city text, owner_id uuid, is_active boolean default true, subscription_status text default 'active', organization_id bigint, visibility_mode text default 'PUBLIC', shop_type text default 'branch', group_id bigint, can_view_public_market boolean default true, default_margin_percent numeric not null default 0, slug text);
create table user_branches (user_id uuid not null, branch_id integer not null);
create table products (id bigint generated by default as identity primary key, product_code text not null, product_name text not null, brand text, model text, shop_id bigint, quantity integer default 0, price numeric default 0, organization_id bigint, warehouse_id bigint);
create table orders (id bigint generated by default as identity primary key, from_shop_id bigint, to_shop_id bigint, status text default 'pending', total_amount numeric default 0, created_at timestamptz default now(), notes text, updated_at timestamptz default now(), created_by uuid, approved_by uuid, approved_at timestamptz);
create table order_items (id bigint generated by default as identity primary key, order_id bigint references orders(id), product_id bigint, quantity integer default 1, price numeric default 0, approved_quantity numeric default 0, approval_reviewed boolean not null default false);
create table notifications (id bigint generated by default as identity primary key, shop_id bigint not null, title text not null, message text not null, type text default 'info', is_read boolean default false, created_at timestamptz default now());
create table gl_accounts (id bigint generated by default as identity primary key, organization_id bigint not null, code text not null, name text not null, parent_id bigint, type text not null, is_group boolean not null default false, is_active boolean not null default true);
create table gl_parties (id bigint generated by default as identity primary key, organization_id bigint not null, branch_id bigint, type text not null default 'customer', name text not null, account_id bigint, is_active boolean not null default true);
create table gl_journal_entries (id bigint generated by default as identity primary key, organization_id bigint not null, entry_no integer not null, entry_year integer not null, date date not null, description text, branch_id bigint, status text not null default 'posted', created_by uuid default auth.uid(), created_at timestamptz default now(), entry_type text not null default 'general', notes text, unique (organization_id, entry_year, entry_no));
create table gl_journal_lines (id bigint generated by default as identity primary key, entry_id bigint not null references gl_journal_entries(id), account_id bigint not null, debit numeric not null default 0, credit numeric not null default 0, branch_id bigint, note text, party_id bigint);
create table gl_journal_entry_counters (organization_id bigint not null, entry_year integer not null, last_no bigint not null default 0, updated_at timestamptz not null default now(), primary key (organization_id, entry_year));
create table gl_sales_return_sequences (organization_id bigint not null, return_year integer not null, last_no bigint not null default 0, primary key (organization_id, return_year));

create function is_admin() returns boolean language sql security definer set search_path to 'public' as $$ select coalesce((select is_admin from public.profiles where id = auth.uid()), false); $$;
create function my_organizations() returns setof bigint language sql stable security definer set search_path to 'public' as $$
  with me as (select coalesce(is_admin,false) as adm, role, store_id from profiles where id = auth.uid())
  select o.id::bigint from organizations o, me where me.adm or me.role = 'admin'
  union
  select distinct s.organization_id::bigint from shops s where s.organization_id is not null and (
    s.owner_id = auth.uid() or s.id in (select branch_id from user_branches where user_id = auth.uid())
    or s.id = (select store_id from profiles where id = auth.uid())
    or s.organization_id in (select organization_id from organization_members where user_id = auth.uid())) $$;
-- stand-ins for the live ones that S6a may call
create function next_gl_sales_quotation_no(p_org_id bigint, p_branch_id bigint, p_year integer) returns bigint language sql security definer set search_path=public as $$ select 1::bigint $$;
create function handle_new_user() returns trigger language plpgsql security definer as $$ begin return new; end $$;
-- ORIGINAL live functions
create function next_gl_sales_return_no(p_org_id bigint, p_year integer) returns bigint language plpgsql security definer set search_path = public as $$
declare v_no bigint;
begin
  if p_org_id is null or p_org_id <= 0 or p_year < 2000 or p_year > 9999 then
    raise exception 'Invalid organization or return year';
  end if;
  insert into public.gl_sales_return_sequences(organization_id, return_year, last_no)
  values (p_org_id, p_year, 1)
  on conflict (organization_id, return_year)
  do update set last_no = public.gl_sales_return_sequences.last_no + 1
  returning last_no into v_no;
  return v_no;
end;
$$;

-- RLS replica for notifications (original permissive insert policy)
alter table notifications enable row level security;
create policy "Allow insert notifications" on notifications for insert to authenticated with check (true);
create policy notif_select on notifications for select to authenticated using (shop_id in (select id from shops where owner_id = auth.uid()));
revoke all on function next_gl_sales_return_no(bigint,integer) from public;
alter table products add column if not exists selling_price numeric, add column if not exists barcode text, add column if not exists warehouse_id bigint;
create table gl_treasuries (id bigint generated by default as identity primary key, organization_id bigint not null, branch_id bigint, name text not null, kind text not null default 'cash', account_id bigint, is_active boolean not null default true);
create table warehouses (id bigint generated by default as identity primary key, organization_id bigint not null, branch_id bigint, name text not null, is_default boolean not null default false);
alter table gl_parties add column if not exists credit_days integer not null default 0, add column if not exists parent_id bigint;
create table gl_sales_invoices (id bigint generated by default as identity primary key, organization_id bigint not null, branch_id bigint, invoice_no integer not null, invoice_year integer not null, date date not null, party_id bigint, customer_name text, payment_type text not null default 'cash', treasury_account_id bigint, paid_amount numeric not null default 0, subtotal numeric not null default 0, tax_rate numeric not null default 15, tax_amount numeric not null default 0, tax_inclusive boolean not null default false, total numeric not null default 0, items jsonb not null default '[]', notes text, entry_id bigint, status text not null default 'posted', created_at timestamptz default now(), shift_id bigint);
create unique index gl_sales_invoices_branch_number_uidx on gl_sales_invoices (organization_id, coalesce(branch_id,0), invoice_year, invoice_no);
create table gl_sales_payments (id bigint generated by default as identity primary key, organization_id bigint not null, invoice_id bigint not null, method text not null, treasury_account_id bigint, customer_account_id bigint, party_id bigint, amount numeric not null default 0, created_at timestamptz default now());
create table gl_stock_moves (id bigint generated by default as identity primary key, organization_id bigint not null, branch_id bigint, product_id bigint not null, move_type text not null, qty numeric not null, unit_cost numeric, ref_type text, ref_id bigint, notes text, created_at timestamptz not null default now(), created_by uuid);
create function can_access_branch(bid integer) returns boolean language sql security definer set search_path to 'public' as $$
  select public.is_admin() or bid = (select store_id from public.profiles where id = auth.uid())
   or exists (select 1 from public.shops where id = bid and owner_id = auth.uid())
   or exists (select 1 from public.user_branches ub where ub.user_id = auth.uid() and ub.branch_id = bid)
   or exists (select 1 from public.shops s join public.organization_members om on om.organization_id = s.organization_id where s.id = bid and om.user_id = auth.uid()); $$;
